import { useEffect, useMemo, useState } from 'react';
import {
  AlertCircle,
  BarChart3,
  Bell,
  BookOpen,
  Bot,
  Calendar,
  Check,
  CheckCircle2,
  ChevronDown,
  ChevronRight,
  Clipboard,
  Clock3,
  Copy,
  FileText,
  FlaskConical,
  Gauge,
  Home,
  Info,
  Lightbulb,
  ListChecks,
  Menu,
  MessageSquare,
  Moon,
  MoreHorizontal,
  PanelLeftClose,
  PanelLeftOpen,
  Plus,
  Search,
  Send,
  Settings,
  Sparkles,
  Sun,
  Target,
  Timer,
  TrendingUp,
  Upload,
  Zap,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';

type Page = 'dashboard' | 'chat' | 'research' | 'tasks' | 'meetings' | 'prompts' | 'analytics' | 'settings' | 'about';
type Theme = 'light' | 'dark';

type ActivityItem = { icon: LucideIcon; title: string; detail: string; time: string; color: string };

const navGroups = [
  { label: 'Workspace', items: [
    { id: 'dashboard' as Page, label: 'Dashboard', icon: Home },
    { id: 'chat' as Page, label: 'AI Chatbot', icon: MessageSquare },
    { id: 'research' as Page, label: 'Research Assistant', icon: FlaskConical },
    { id: 'tasks' as Page, label: 'Task Planner', icon: ListChecks },
    { id: 'meetings' as Page, label: 'Meeting Summarizer', icon: FileText },
  ] },
  { label: 'Insights', items: [
    { id: 'prompts' as Page, label: 'Prompt Library', icon: BookOpen },
    { id: 'analytics' as Page, label: 'Productivity Analytics', icon: BarChart3 },
  ] },
  { label: 'Account', items: [
    { id: 'settings' as Page, label: 'Settings', icon: Settings },
    { id: 'about' as Page, label: 'About', icon: Info },
  ] },
];

const activities: ActivityItem[] = [
  { icon: FileText, title: 'Meeting notes summarized', detail: 'Product sync · 8 action items', time: '12 min ago', color: 'text-brand-600 bg-brand-100 dark:bg-brand-950/50' },
  { icon: FlaskConical, title: 'Research completed', detail: 'Sustainable workplace trends', time: '1 hr ago', color: 'text-rose-600 bg-rose-100 dark:bg-rose-950/50' },
  { icon: ListChecks, title: 'Daily plan optimized', detail: '12 tasks organized', time: '2 hrs ago', color: 'text-fuchsia-600 bg-fuchsia-100 dark:bg-fuchsia-950/50' },
  { icon: MessageSquare, title: 'Draft response created', detail: 'Client proposal follow-up', time: '3 hrs ago', color: 'text-rose-600 bg-rose-100 dark:bg-rose-950/50' },
];

const suggestedPrompts = ['Write a professional email', 'Summarize this document', 'Plan my day', 'Explain AI ethics', 'Create a meeting agenda', 'Research renewable energy'];

function App() {
  const [page, setPage] = useState<Page>('dashboard');
  const [theme, setTheme] = useState<Theme>('light');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme]);

  const pageTitle = useMemo(() => {
    const item = navGroups.flatMap((group) => group.items).find((navItem) => navItem.id === page);
    return item?.label ?? 'Dashboard';
  }, [page]);

  return (
    <div className="min-h-screen bg-pink-50/40 dark:bg-gray-950">
      <div className="fixed inset-0 pointer-events-none overflow-hidden">
        <div className="absolute -top-40 -right-40 h-96 w-96 rounded-full bg-brand-200/30 dark:bg-brand-900/10 blur-3xl" />
        <div className="absolute top-1/2 -left-40 h-80 w-80 rounded-full bg-rose-200/20 dark:bg-rose-900/10 blur-3xl" />
      </div>
      <Sidebar page={page} setPage={setPage} open={sidebarOpen} setOpen={setSidebarOpen} />
      <div className={`relative transition-all duration-300 ${sidebarOpen ? 'lg:ml-64' : 'lg:ml-[76px]'}`}>
        <Topbar title={pageTitle} theme={theme} setTheme={setTheme} onMenu={() => setSidebarOpen(!sidebarOpen)} />
        <main className="p-4 sm:p-6 lg:p-8 max-w-[1600px] mx-auto">
          {page === 'dashboard' && <Dashboard setPage={setPage} />}
          {page === 'chat' && <Chatbot />}
          {page === 'research' && <ResearchAssistant />}
          {page === 'tasks' && <TaskPlanner />}
          {page === 'meetings' && <MeetingSummarizer />}
          {page === 'prompts' && <PromptLibrary />}
          {page === 'analytics' && <Analytics />}
          {page === 'settings' && <SettingsPage theme={theme} setTheme={setTheme} />}
          {page === 'about' && <About />}
        </main>
      </div>
    </div>
  );
}

function Sidebar({ page, setPage, open, setOpen }: { page: Page; setPage: (page: Page) => void; open: boolean; setOpen: (open: boolean) => void }) {
  return (
    <aside className={`fixed z-30 inset-y-0 left-0 bg-white/90 dark:bg-gray-900/90 backdrop-blur-xl border-r border-pink-100/60 dark:border-gray-800 transition-all duration-300 ${open ? 'w-64' : 'w-[76px]'} hidden lg:block`}>
      <div className="h-full flex flex-col p-4">
        <div className={`flex items-center mb-8 ${open ? 'justify-between' : 'justify-center'}`}>
          <button onClick={() => setPage('dashboard')} className="flex items-center gap-3 group">
            <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-brand-400 to-rose-400 flex items-center justify-center text-white shadow-lg shadow-brand-500/20 group-hover:scale-105 transition-transform">
              <Sparkles size={21} />
            </div>
            {open && <div className="text-left"><p className="font-display font-bold text-gray-900 dark:text-white leading-tight">Nexa</p><p className="text-[10px] text-gray-500 tracking-widest uppercase">Workplace AI</p></div>}
          </button>
          {open && <button onClick={() => setOpen(false)} className="btn-ghost p-2"><PanelLeftClose size={17} /></button>}
        </div>
        {open && <div className="px-3 mb-3"><p className="text-[10px] uppercase tracking-widest text-gray-400 font-semibold">Navigation</p></div>}
        <nav className="space-y-5 flex-1 overflow-y-auto scrollbar-thin">
          {navGroups.map((group) => <div key={group.label}>
            {open && <p className="px-3 mb-2 text-xs font-semibold text-gray-400 dark:text-gray-600">{group.label}</p>}
            <div className="space-y-1">
              {group.items.map((item) => <button key={item.id} onClick={() => setPage(item.id)} title={!open ? item.label : undefined} className={`nav-link w-full ${page === item.id ? 'nav-link-active' : ''} ${!open ? 'justify-center px-2' : ''}`}>
                <item.icon size={18} strokeWidth={page === item.id ? 2.3 : 1.8} /><span className={open ? '' : 'sr-only'}>{item.label}</span>
                {item.id === 'chat' && open && <span className="ml-auto h-2 w-2 rounded-full bg-rose-500" />}
              </button>)}
            </div>
          </div>)}
        </nav>
        <div className={`mt-4 p-3 rounded-2xl bg-gradient-to-br from-brand-500 to-brand-700 text-white relative overflow-hidden ${open ? '' : 'p-2'}`}>
          <div className="absolute -right-4 -top-4 h-16 w-16 rounded-full border border-white/20" />
          {open ? <><div className="flex items-center gap-2 mb-2"><Zap size={15} className="text-rose-300" /><span className="text-xs font-semibold">Pro workspace</span></div><p className="text-[11px] text-brand-100 leading-relaxed mb-3">Unlock unlimited AI workflows and advanced insights.</p><button className="w-full py-1.5 rounded-lg bg-white/15 hover:bg-white/25 text-xs font-medium transition-colors">View plan</button></> : <Zap size={18} className="mx-auto text-rose-300" />}
        </div>
        {open && <div className="flex items-center gap-3 mt-5 px-2"><div className="h-9 w-9 rounded-full bg-gradient-to-br from-brand-400 to-brand-600 flex items-center justify-center text-white text-sm font-bold">OS</div><div className="min-w-0 flex-1"><p className="text-sm font-semibold truncate text-gray-800 dark:text-gray-200">Oratilwe Seleke</p><p className="text-[11px] text-gray-500 truncate">Administrator</p></div><MoreHorizontal size={17} className="text-gray-400" /></div>}
      </div>
    </aside>
  );
}

function Topbar({ title, theme, setTheme, onMenu }: { title: string; theme: Theme; setTheme: (theme: Theme) => void; onMenu: () => void }) {
  return <header className="h-20 border-b border-gray-200/80 dark:border-gray-800/80 bg-white/70 dark:bg-gray-900/70 backdrop-blur-xl flex items-center justify-between px-4 sm:px-6 lg:px-8 sticky top-0 z-20">
    <div className="flex items-center gap-3"><button onClick={onMenu} className="btn-ghost lg:hidden p-2"><Menu size={20} /></button><button onClick={onMenu} className="btn-ghost hidden lg:flex p-2"><PanelLeftOpen size={18} /></button><div><h1 className="font-display text-xl font-bold text-gray-900 dark:text-white">{title}</h1><p className="hidden sm:block text-xs text-gray-500 mt-0.5">Tuesday, September 9, 2026</p></div></div>
    <div className="flex items-center gap-2 sm:gap-3"><div className="hidden md:flex items-center gap-2 px-3 py-2 rounded-xl bg-gray-100 dark:bg-gray-800 text-gray-400 text-sm"><Search size={16} /><span>Search workspace</span><kbd className="ml-5 text-[10px] border border-gray-300 dark:border-gray-600 px-1.5 py-0.5 rounded">⌘ K</kbd></div><button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} className="btn-ghost p-2.5" aria-label="Toggle theme">{theme === 'light' ? <Moon size={18} /> : <Sun size={18} />}</button><button className="btn-ghost p-2.5 relative"><Bell size={18} /><span className="absolute top-1.5 right-1.5 h-2 w-2 rounded-full bg-rose-500 ring-2 ring-white dark:ring-gray-900" /></button><div className="hidden sm:flex items-center gap-2 pl-2 border-l border-gray-200 dark:border-gray-700"><div className="h-9 w-9 rounded-full bg-gradient-to-br from-brand-400 to-brand-600 flex items-center justify-center text-white text-xs font-bold">OS</div><ChevronDown size={14} className="text-gray-400" /></div></div>
  </header>;
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-7 animate-fade-in"><div>{eyebrow && <p className="text-xs font-semibold text-brand-600 dark:text-brand-400 uppercase tracking-widest mb-2">{eyebrow}</p>}<h2 className="font-display text-2xl sm:text-3xl font-bold text-gray-900 dark:text-white tracking-tight">{title}</h2>{description && <p className="text-sm text-gray-500 dark:text-gray-400 mt-2 max-w-2xl leading-relaxed">{description}</p>}</div>{action}</div>;
}

function StatCard({ label, value, change, icon: Icon, color, detail }: { label: string; value: string; change?: string; icon: LucideIcon; color: string; detail?: string }) {
  return <div className="glass-card p-5 animate-slide-up"><div className="flex items-start justify-between"><div className={`h-10 w-10 rounded-xl flex items-center justify-center ${color}`}><Icon size={19} /></div>{change && <span className="badge bg-rose-100 dark:bg-rose-950/50 text-rose-700 dark:text-rose-400"><TrendingUp size={12} />{change}</span>}</div><p className="text-sm text-gray-500 dark:text-gray-400 mt-4">{label}</p><p className="font-display text-2xl font-bold text-gray-900 dark:text-white mt-1">{value}</p>{detail && <p className="text-xs text-gray-400 mt-1">{detail}</p>}</div>;
}

function Dashboard({ setPage }: { setPage: (page: Page) => void }) {
  const quickActions = [{ id: 'chat' as Page, icon: MessageSquare, title: 'AI Chatbot', text: 'Ask anything', color: 'from-brand-500 to-brand-600' }, { id: 'research' as Page, icon: FlaskConical, title: 'Research', text: 'Get insights fast', color: 'from-rose-500 to-rose-600' }, { id: 'tasks' as Page, icon: ListChecks, title: 'Plan tasks', text: 'Organize your day', color: 'from-brand-400 to-brand-500' }, { id: 'meetings' as Page, icon: FileText, title: 'Summarize', text: 'Extract key points', color: 'from-rose-500 to-rose-600' }];
  return <div><PageHeader eyebrow="Good morning, Oratilwe" title="Your productivity cockpit" description="Here's your AI-powered overview for today. You are making excellent progress." action={<button onClick={() => setPage('chat')} className="btn-primary"><Sparkles size={17} />Ask Nexa</button>} />
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6"><StatCard label="Productivity score" value="87%" change="12.4%" icon={Gauge} color="text-brand-600 bg-brand-100 dark:bg-brand-950/50" detail="Excellent this week" /><StatCard label="Tasks completed" value="24" change="8.2%" icon={CheckCircle2} color="text-rose-600 bg-rose-100 dark:bg-rose-950/50" detail="of 28 planned" /><StatCard label="Time saved" value="4h 32m" change="18.6%" icon={Clock3} color="text-fuchsia-600 bg-fuchsia-100 dark:bg-fuchsia-950/50" detail="This week" /><StatCard label="AI interactions" value="68" change="24.1%" icon={Bot} color="text-rose-600 bg-rose-100 dark:bg-rose-950/50" detail="Across all tools" /></div>
    <div className="grid lg:grid-cols-[1.4fr_1fr] gap-6 mb-6"><div className="glass-card p-6"><div className="flex items-center justify-between mb-5"><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Quick actions</h3><p className="text-xs text-gray-500 mt-1">Jump into your most-used workflows</p></div><Zap size={18} className="text-fuchsia-500" /></div><div className="grid grid-cols-2 sm:grid-cols-4 gap-3">{quickActions.map((item) => <button key={item.id} onClick={() => setPage(item.id)} className="group text-left p-3 rounded-xl border border-gray-100 dark:border-gray-800 hover:border-brand-200 dark:hover:border-brand-800 hover:bg-gray-50 dark:hover:bg-gray-800/70 transition-all"><div className={`h-9 w-9 rounded-lg bg-gradient-to-br ${item.color} text-white flex items-center justify-center mb-3 group-hover:scale-110 transition-transform`}><item.icon size={17} /></div><p className="text-sm font-semibold text-gray-800 dark:text-gray-200">{item.title}</p><p className="text-[11px] text-gray-500 mt-1">{item.text}</p></button>)}</div></div><div className="glass-card p-6"><div className="flex justify-between items-center mb-4"><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Weekly momentum</h3><p className="text-xs text-gray-500 mt-1">Your activity at a glance</p></div><span className="badge bg-rose-100 dark:bg-rose-950/50 text-rose-700 dark:text-rose-400"><TrendingUp size={12} />+14%</span></div><MiniChart /></div></div>
    <div className="grid lg:grid-cols-[1.2fr_1fr] gap-6"><div className="glass-card p-6"><div className="flex items-center justify-between mb-5"><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Recent activity</h3><p className="text-xs text-gray-500 mt-1">Your latest AI-assisted work</p></div><button onClick={() => setPage('analytics')} className="text-xs text-brand-600 dark:text-brand-400 font-medium hover:underline">View analytics <ChevronRight size={13} className="inline" /></button></div><div className="space-y-4">{activities.map((activity) => <div key={activity.title} className="flex items-center gap-3"><div className={`h-9 w-9 rounded-lg flex items-center justify-center shrink-0 ${activity.color}`}><activity.icon size={16} /></div><div className="min-w-0 flex-1"><p className="text-sm font-medium text-gray-800 dark:text-gray-200 truncate">{activity.title}</p><p className="text-xs text-gray-500 truncate">{activity.detail}</p></div><span className="text-[11px] text-gray-400 shrink-0">{activity.time}</span></div>)}</div></div><div className="glass-card p-6"><div className="flex items-center justify-between mb-4"><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Productivity impact</h3><p className="text-xs text-gray-500 mt-1">Average time saved with Nexa</p></div><div className="h-9 w-9 rounded-xl bg-rose-100 dark:bg-rose-950/50 text-rose-600 flex items-center justify-center"><Target size={18} /></div></div><div className="space-y-4"><ImpactRow label="Email writing" before="10 min" after="1 min" percent={90} color="bg-brand-500" /><ImpactRow label="Meeting summaries" before="30 min" after="2 min" percent={93} color="bg-rose-500" /><ImpactRow label="Research" before="60 min" after="10 min" percent={83} color="bg-fuchsia-500" /><ImpactRow label="Task planning" before="20 min" after="2 min" percent={90} color="bg-rose-400" /></div></div></div>
  </div>;
}

function MiniChart() { const values = [34, 46, 39, 65, 54, 73, 87]; return <div className="h-36 flex items-end gap-2 pt-3">{values.map((value, index) => <div key={index} className="flex-1 flex flex-col items-center gap-2 h-full justify-end"><div className={`w-full max-w-8 rounded-t-md transition-all duration-500 ${index === values.length - 1 ? 'bg-brand-600' : 'bg-brand-200 dark:bg-brand-900/70'}`} style={{ height: `${value}%` }} /><span className="text-[10px] text-gray-400">{['M', 'T', 'W', 'T', 'F', 'S', 'S'][index]}</span></div>)}</div>; }
function ImpactRow({ label, before, after, percent, color }: { label: string; before: string; after: string; percent: number; color: string }) { return <div><div className="flex justify-between text-xs mb-1.5"><span className="font-medium text-gray-700 dark:text-gray-300">{label}</span><span className="text-gray-400">{before} <ChevronRight size={11} className="inline" /> <strong className="text-rose-600">{after}</strong></span></div><div className="h-1.5 bg-gray-100 dark:bg-gray-800 rounded-full overflow-hidden"><div className={`h-full ${color} rounded-full`} style={{ width: `${percent}%` }} /></div></div>; }

function Chatbot() {
  type ChatMessage = { role: 'user' | 'assistant'; text: string; time: string };
  const [messages, setMessages] = useState<ChatMessage[]>([{ role: 'assistant', text: "Good morning, Oratilwe. I'm Nexa, your workplace productivity assistant. I can help you draft communications, summarize documents, brainstorm ideas, or plan your day. What would you like to work on?", time: '9:41 AM' }]);
  const [input, setInput] = useState(''); const [loading, setLoading] = useState(false); const [copied, setCopied] = useState<number | null>(null);
  const send = (text = input) => { if (!text.trim() || loading) return; setMessages((current) => [...current, { role: 'user', text, time: 'Now' }]); setInput(''); setLoading(true); setTimeout(() => { setMessages((current) => [...current, { role: 'assistant', text: `Here's a polished starting point based on your request:\n\nI can help you turn this into a clear, professional outcome. Consider defining the desired result, the audience, and the deadline first. Then break the work into the smallest actionable next steps and assign focused time blocks.\n\nWould you like me to make this more specific to your team or format it as a ready-to-use draft?`, time: 'Now' }]); setLoading(false); }, 900); };
  return <div className="max-w-5xl mx-auto"><PageHeader eyebrow="Your AI copilot" title="How can I help today?" description="A thoughtful assistant for your everyday workplace tasks. Your conversation stays private to this session." action={<button className="btn-secondary"><Plus size={16} />New conversation</button>} /><div className="glass-card overflow-hidden"><div className="px-5 py-4 border-b border-gray-100 dark:border-gray-800 flex items-center justify-between"><div className="flex items-center gap-3"><div className="h-9 w-9 rounded-xl bg-gradient-to-br from-brand-400 to-rose-400 flex items-center justify-center text-white"><Bot size={18} /></div><div><p className="text-sm font-semibold text-gray-900 dark:text-white">Nexa Assistant</p><p className="text-[11px] text-rose-600 flex items-center gap-1"><span className="h-1.5 w-1.5 rounded-full bg-rose-500" />Online · Ready to help</p></div></div><button className="btn-ghost p-2"><MoreHorizontal size={18} /></button></div><div className="h-[430px] overflow-y-auto p-5 space-y-5 scrollbar-thin">{messages.map((message, index) => <div key={index} className={`flex gap-3 animate-slide-up ${message.role === 'user' ? 'flex-row-reverse' : ''}`}><div className={`h-8 w-8 rounded-lg shrink-0 flex items-center justify-center ${message.role === 'assistant' ? 'bg-brand-100 dark:bg-brand-950/50 text-brand-600' : 'bg-gradient-to-br from-brand-400 to-brand-600 text-white'}`}>{message.role === 'assistant' ? <Sparkles size={15} /> : <span className="text-[11px] font-bold">OS</span>}</div><div className={`max-w-[82%] ${message.role === 'user' ? 'items-end' : ''}`}><div className={`px-4 py-3 rounded-2xl text-sm leading-relaxed whitespace-pre-line ${message.role === 'assistant' ? 'bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-200 rounded-tl-sm' : 'bg-brand-600 text-white rounded-tr-sm'}`}>{message.text}</div><div className={`flex items-center gap-2 mt-1.5 text-[10px] text-gray-400 ${message.role === 'user' ? 'justify-end' : ''}`}><span>{message.time}</span>{message.role === 'assistant' && <button onClick={() => { navigator.clipboard.writeText(message.text); setCopied(index); setTimeout(() => setCopied(null), 1500); }} className="hover:text-brand-600">{copied === index ? <Check size={12} /> : <Copy size={12} />}</button>}</div></div></div>)}{loading && <div className="flex gap-3"><div className="h-8 w-8 rounded-lg bg-brand-100 dark:bg-brand-950/50 text-brand-600 flex items-center justify-center"><Sparkles size={15} /></div><div className="px-4 py-3 rounded-2xl rounded-tl-sm bg-gray-100 dark:bg-gray-800 text-brand-600"><span className="typing-dot" /><span className="typing-dot" /><span className="typing-dot" /></div></div>}</div><div className="px-5 pb-4"><div className="flex gap-2 overflow-x-auto pb-3 scrollbar-thin">{suggestedPrompts.map((prompt) => <button key={prompt} onClick={() => send(prompt)} className="shrink-0 px-3 py-1.5 rounded-lg border border-gray-200 dark:border-gray-700 text-xs text-gray-600 dark:text-gray-400 hover:border-brand-300 hover:text-brand-600 transition-colors">{prompt}</button>)}</div><div className="flex items-end gap-2 p-2 rounded-xl bg-gray-100 dark:bg-gray-800 border border-transparent focus-within:border-brand-400 transition-colors"><textarea value={input} onChange={(event) => setInput(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); send(); } }} rows={1} placeholder="Message Nexa..." className="flex-1 bg-transparent resize-none outline-none px-2 py-1.5 text-sm text-gray-800 dark:text-gray-200 placeholder-gray-400" /><button onClick={() => send()} disabled={!input.trim() || loading} className="h-9 w-9 rounded-lg bg-brand-600 text-white flex items-center justify-center hover:bg-brand-700 disabled:opacity-40 transition-colors"><Send size={16} /></button></div><p className="text-[10px] text-gray-400 text-center mt-2">Nexa can make mistakes. Review important information before using it.</p></div></div></div>;
}

function ToolShell({ icon: Icon, color, title, description, children, action }: { icon: LucideIcon; color: string; title: string; description: string; children: React.ReactNode; action?: React.ReactNode }) { return <div><PageHeader eyebrow="AI workflow" title={title} description={description} action={action} /><div className="grid lg:grid-cols-[1fr_1fr] gap-6">{children}</div><div className={`fixed bottom-5 right-5 h-12 w-12 rounded-2xl ${color} text-white shadow-xl flex items-center justify-center lg:hidden`}><Icon size={21} /></div></div>; }
function ResultCard({ title, icon: Icon, children, loading, onCopy }: { title: string; icon: LucideIcon; children: React.ReactNode; loading?: boolean; onCopy?: () => void }) { return <div className="glass-card p-6 min-h-[400px]"><div className="flex items-center justify-between mb-5"><div className="flex items-center gap-2"><div className="h-8 w-8 rounded-lg bg-rose-100 dark:bg-rose-950/50 text-rose-600 flex items-center justify-center"><Icon size={16} /></div><h3 className="font-display font-bold text-gray-900 dark:text-white">{title}</h3></div>{onCopy && <button onClick={onCopy} className="btn-ghost p-2" title="Copy result"><Copy size={16} /></button>}</div>{loading ? <div className="space-y-4 animate-pulse"><div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-5/6" /><div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-full" /><div className="h-3 bg-gray-200 dark:bg-gray-800 rounded w-4/6" /><div className="h-24 bg-gray-100 dark:bg-gray-800 rounded-xl mt-6" /></div> : children}</div>; }

function ResearchAssistant() { const [text, setText] = useState(''); const [level, setLevel] = useState('Professional'); const [loading, setLoading] = useState(false); const [generated, setGenerated] = useState(false); const run = () => { if (!text.trim()) return; setLoading(true); setGenerated(false); setTimeout(() => { setLoading(false); setGenerated(true); }, 1100); }; return <ToolShell icon={FlaskConical} color="bg-rose-600" title="Research, distilled." description="Turn dense articles, reports, and topics into decision-ready insights in seconds."><div className="glass-card p-6 h-fit"><div className="flex items-center justify-between mb-4"><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Your source material</h3><p className="text-xs text-gray-500 mt-1">Paste text or describe a topic to begin</p></div><button className="btn-ghost text-xs"><Upload size={14} />Upload</button></div><textarea value={text} onChange={(event) => setText(event.target.value)} placeholder="Paste an article, report, research paper, or simply enter a topic..." className="input-field min-h-[230px] resize-none text-sm leading-relaxed" /><div className="flex items-center justify-between mt-4 gap-3"><div><label className="text-xs font-medium text-gray-600 dark:text-gray-400 block mb-1.5">Summary level</label><select value={level} onChange={(event) => setLevel(event.target.value)} className="input-field py-2 text-sm w-auto"><option>Beginner</option><option>Professional</option><option>Executive</option></select></div><button onClick={run} disabled={!text.trim() || loading} className="btn-primary mt-5"><Sparkles size={16} />{loading ? 'Analyzing...' : 'Generate insights'}</button></div><div className="mt-5 pt-4 border-t border-gray-100 dark:border-gray-800 flex items-start gap-2 text-[11px] text-gray-500"><AlertCircle size={14} className="text-fuchsia-500 shrink-0 mt-0.5" />AI-generated research is a starting point. Verify facts and sources before sharing.</div></div><ResultCard title="Executive summary" icon={FileText} loading={loading} onCopy={() => navigator.clipboard.writeText('Executive summary')}><div className={generated ? 'animate-slide-up' : ''}>{generated ? <><p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed mb-5">The provided material explores how sustainable workplace practices are moving from a differentiator to an operational standard. Organizations that connect environmental initiatives to employee experience see stronger engagement and measurable cost efficiencies.</p><Insight label="Key insights" items={['Hybrid work can reduce office-related emissions by up to 30%.', 'Employee participation is the strongest predictor of program success.', 'Transparent measurement builds trust and accelerates adoption.']} /><Insight label="Recommendations" items={['Start with one measurable pilot program.', 'Create a simple internal reporting rhythm.', 'Invite employees to shape the next iteration.']} /></> : <div className="h-full min-h-[300px] flex flex-col items-center justify-center text-center"><div className="h-14 w-14 rounded-2xl bg-rose-100 dark:bg-rose-950/50 text-rose-600 flex items-center justify-center mb-4"><FlaskConical size={25} /></div><p className="text-sm font-medium text-gray-700 dark:text-gray-300">Your insights will appear here</p><p className="text-xs text-gray-400 mt-1 max-w-[220px]">Add source material and select your preferred summary level.</p></div>}</div></ResultCard></ToolShell>; }
function Insight({ label, items }: { label: string; items: string[] }) { return <div className="mb-5"><h4 className="text-xs font-bold text-gray-800 dark:text-gray-200 uppercase tracking-wider mb-2">{label}</h4><ul className="space-y-2">{items.map((item) => <li key={item} className="flex gap-2 text-sm text-gray-600 dark:text-gray-400 leading-relaxed"><CheckCircle2 size={14} className="text-rose-500 mt-0.5 shrink-0" />{item}</li>)}</ul></div>; }

function TaskPlanner() { const [taskText, setTaskText] = useState(''); const [tasks, setTasks] = useState([{ title: 'Review quarterly budget proposal', priority: 'Urgent', due: 'Today, 11:00 AM', duration: '45 min', done: false }, { title: 'Prepare team sync agenda', priority: 'Important', due: 'Today, 2:00 PM', duration: '30 min', done: true }, { title: 'Update project documentation', priority: 'Low priority', due: 'Tomorrow', duration: '60 min', done: false }, { title: 'Respond to client feedback', priority: 'Important', due: 'Today, 4:30 PM', duration: '25 min', done: false }]); const add = () => { if (taskText.trim()) { setTasks((current) => [{ title: taskText, priority: 'Important', due: 'Today', duration: '30 min', done: false }, ...current]); setTaskText(''); } }; const toggle = (index: number) => setTasks((current) => current.map((task, taskIndex) => taskIndex === index ? { ...task, done: !task.done } : task)); return <div><PageHeader eyebrow="Executive productivity coach" title="Make time work for you." description="Prioritize what matters, create realistic schedules, and protect your focus." action={<button className="btn-primary"><Calendar size={16} />Weekly view</button>} /><div className="grid xl:grid-cols-[1.2fr_1fr] gap-6"><div className="glass-card p-6"><div className="flex items-center justify-between mb-5"><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Today's focus</h3><p className="text-xs text-gray-500 mt-1">Tuesday, September 9 · 4 tasks remaining</p></div><span className="badge bg-brand-100 dark:bg-brand-950/50 text-brand-700 dark:text-brand-300">68% planned</span></div><div className="h-2 rounded-full bg-gray-100 dark:bg-gray-800 mb-6"><div className="h-full w-[68%] rounded-full bg-gradient-to-r from-brand-400 to-rose-400" /></div><div className="space-y-3">{tasks.map((task, index) => <div key={`${task.title}-${index}`} className={`flex items-center gap-3 p-3 rounded-xl border transition-all ${task.done ? 'bg-gray-50 dark:bg-gray-800/40 border-transparent opacity-60' : 'border-gray-100 dark:border-gray-800 hover:border-brand-200 dark:hover:border-brand-800'}`}><button onClick={() => toggle(index)} className={`h-5 w-5 rounded-md border-2 flex items-center justify-center shrink-0 ${task.done ? 'bg-rose-500 border-rose-500 text-white' : 'border-gray-300 dark:border-gray-600'}`}>{task.done && <Check size={13} />}</button><div className="min-w-0 flex-1"><p className={`text-sm font-medium text-gray-800 dark:text-gray-200 ${task.done ? 'line-through' : ''}`}>{task.title}</p><div className="flex items-center gap-2 mt-1"><span className={`text-[10px] font-semibold ${task.priority === 'Urgent' ? 'text-red-500' : task.priority === 'Important' ? 'text-fuchsia-600' : 'text-gray-400'}`}>{task.priority}</span><span className="text-[10px] text-gray-400">· {task.due}</span></div></div><span className="hidden sm:block text-[11px] text-gray-400">{task.duration}</span><button className="btn-ghost p-1.5 text-gray-400"><MoreHorizontal size={16} /></button></div>)}</div><div className="flex gap-2 mt-5"><input value={taskText} onChange={(event) => setTaskText(event.target.value)} onKeyDown={(event) => event.key === 'Enter' && add()} placeholder="Add a task..." className="input-field" /><button onClick={add} className="btn-primary px-3"><Plus size={18} /></button></div></div><div className="space-y-6"><div className="glass-card p-6"><div className="flex items-center gap-2 mb-5"><div className="h-8 w-8 rounded-lg bg-fuchsia-100 dark:bg-fuchsia-950/50 text-fuchsia-600 flex items-center justify-center"><Clock3 size={16} /></div><div><h3 className="font-display font-bold text-gray-900 dark:text-white">AI-optimized schedule</h3><p className="text-xs text-gray-500 mt-1">Based on your priorities and energy</p></div></div><div className="space-y-4"><ScheduleItem time="9:00" title="Deep work · Budget review" color="bg-brand-500" /><ScheduleItem time="10:00" title="Focus break" color="bg-rose-500" /><ScheduleItem time="11:00" title="Team collaboration" color="bg-fuchsia-500" /><ScheduleItem time="12:30" title="Lunch & recharge" color="bg-gray-300 dark:bg-gray-700" /><ScheduleItem time="2:00" title="Creative work block" color="bg-rose-400" /></div><button className="w-full btn-secondary mt-5 text-sm"><Sparkles size={15} />Optimize my day</button></div><div className="glass-card p-5 bg-gradient-to-br from-brand-500 to-brand-700 text-white border-0"><div className="flex gap-3"><Lightbulb className="text-brand-300 shrink-0" size={19} /><div><p className="text-sm font-semibold">A smarter work rhythm</p><p className="text-xs text-brand-100 leading-relaxed mt-1">Your schedule has 3.5 hours of focused work. Add a 15-minute buffer before your afternoon meeting to reduce context switching.</p></div></div></div></div></div></div>; }
function ScheduleItem({ time, title, color }: { time: string; title: string; color: string }) { return <div className="flex gap-3 items-center"><span className="font-mono text-[10px] text-gray-400 w-8">{time}</span><div className={`w-1 h-8 rounded-full ${color}`} /><p className="text-sm text-gray-700 dark:text-gray-300">{title}</p></div>; }

function MeetingSummarizer() { const [notes, setNotes] = useState(''); const [loading, setLoading] = useState(false); const [generated, setGenerated] = useState(false); const run = () => { if (!notes.trim()) return; setLoading(true); setGenerated(false); setTimeout(() => { setLoading(false); setGenerated(true); }, 1000); }; return <ToolShell icon={FileText} color="bg-rose-600" title="Meetings into momentum." description="Capture the conversation, keep the decisions, and make every next step clear."><div className="glass-card p-6 h-fit"><div className="flex items-center justify-between mb-4"><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Meeting notes</h3><p className="text-xs text-gray-500 mt-1">Paste your notes or transcript below</p></div><span className="badge bg-rose-100 dark:bg-rose-950/50 text-rose-700 dark:text-rose-300"><Timer size={12} />Auto-detect</span></div><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Paste meeting notes, a transcript, or bullet points..." className="input-field min-h-[260px] resize-none text-sm leading-relaxed" /><div className="flex items-center justify-between mt-4"><span className="text-[11px] text-gray-400">{notes.length} characters</span><button onClick={run} disabled={!notes.trim() || loading} className="btn-primary"><Sparkles size={16} />{loading ? 'Summarizing...' : 'Summarize meeting'}</button></div></div><ResultCard title="Meeting brief" icon={Clipboard} loading={loading} onCopy={() => navigator.clipboard.writeText('Meeting brief')}><div className={generated ? 'animate-slide-up' : ''}>{generated ? <><p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed mb-5">The team aligned on the Q4 launch timeline, clarified ownership across workstreams, and identified one dependency that needs resolution before the next milestone.</p><Insight label="Decisions made" items={['Launch target remains October 18.', 'Marketing will own the customer announcement.', 'Weekly cross-functional check-ins start next Tuesday.']} /><Insight label="Action items" items={['Oratilwe · Finalize launch checklist · Friday', 'Maya · Share updated messaging · Wednesday', 'Alex · Confirm vendor timeline · Tomorrow']} /></> : <div className="h-full min-h-[300px] flex flex-col items-center justify-center text-center"><div className="h-14 w-14 rounded-2xl bg-rose-100 dark:bg-rose-950/50 text-rose-600 flex items-center justify-center mb-4"><FileText size={25} /></div><p className="text-sm font-medium text-gray-700 dark:text-gray-300">Your meeting brief will appear here</p><p className="text-xs text-gray-400 mt-1 max-w-[220px]">Paste your notes and let Nexa find the signal.</p></div>}</div></ResultCard></ToolShell>; }

const promptData = [{ title: 'AI Chatbot', description: 'A versatile workplace copilot for clear, ethical responses.', icon: MessageSquare, color: 'bg-brand-100 dark:bg-brand-950/50 text-brand-600', prompt: 'You are an experienced workplace productivity assistant. Provide accurate, professional, ethical, and concise responses. Ask clarifying questions if information is incomplete.' }, { title: 'Research Assistant', description: 'Transform source material into decision-ready insight.', icon: FlaskConical, color: 'bg-rose-100 dark:bg-rose-950/50 text-rose-600', prompt: 'You are a senior research analyst. Summarize the provided information into: Executive Summary, Key Insights, Recommendations, Risks, and Action Items. Use clear professional language.' }, { title: 'Task Planner', description: 'Build practical schedules without inviting burnout.', icon: ListChecks, color: 'bg-fuchsia-100 dark:bg-fuchsia-950/50 text-fuchsia-600', prompt: 'You are an executive productivity coach. Organize tasks according to urgency and importance. Generate a practical schedule that maximizes productivity while avoiding burnout.' }, { title: 'Meeting Summarizer', description: 'Extract decisions and ownership from every conversation.', icon: FileText, color: 'bg-rose-100 dark:bg-rose-950/50 text-rose-600', prompt: 'You are a corporate meeting assistant. Extract Summary, Key decisions, Action items, Deadlines, and Responsible persons. Present the output in a clean professional format.' }];
function PromptLibrary() { const [copied, setCopied] = useState<number | null>(null); return <div><PageHeader eyebrow="Prompt engineering" title="Your best work, reusable." description="A curated library of tested prompt templates that keep every AI workflow consistent, clear, and ethical." action={<button className="btn-primary"><Plus size={16} />Create prompt</button>} /><div className="flex flex-wrap items-center gap-2 mb-6"><button className="badge bg-brand-600 text-white px-4 py-2">All prompts <span className="ml-1 opacity-70">4</span></button><button className="badge bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400 px-4 py-2">Workplace <span className="ml-1 opacity-60">4</span></button><div className="ml-auto flex items-center gap-2"><Search size={16} className="text-gray-400" /><input placeholder="Find a prompt..." className="bg-transparent outline-none text-sm w-32 sm:w-48" /></div></div><div className="grid md:grid-cols-2 gap-5">{promptData.map((item, index) => <div key={item.title} className="glass-card-hover p-6"><div className="flex items-start justify-between mb-4"><div className={`h-10 w-10 rounded-xl flex items-center justify-center ${item.color}`}><item.icon size={19} /></div><button onClick={() => { navigator.clipboard.writeText(item.prompt); setCopied(index); setTimeout(() => setCopied(null), 1500); }} className="btn-ghost p-2" title="Copy prompt">{copied === index ? <Check size={16} className="text-rose-500" /> : <Copy size={16} />}</button></div><h3 className="font-display font-bold text-gray-900 dark:text-white">{item.title}</h3><p className="text-sm text-gray-500 mt-1 mb-5">{item.description}</p><div className="p-4 rounded-xl bg-gray-50 dark:bg-gray-800/70 border border-gray-100 dark:border-gray-800"><p className="font-mono text-xs text-gray-600 dark:text-gray-400 leading-relaxed">{item.prompt}</p></div><div className="flex items-center gap-2 mt-4"><span className="badge bg-gray-100 dark:bg-gray-800 text-gray-500"><Sparkles size={11} />System prompt</span><span className="text-[11px] text-gray-400">Used 24 times</span></div></div>)}</div></div>; }

function Analytics() { return <div><PageHeader eyebrow="Measure what matters" title="Productivity, quantified." description="See how AI is helping you reclaim time and move important work forward." action={<button className="btn-secondary"><Calendar size={16} />Last 30 days <ChevronDown size={14} /></button>} /><div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6"><StatCard label="Tasks completed" value="142" change="18.2%" icon={CheckCircle2} color="text-rose-600 bg-rose-100 dark:bg-rose-950/50" /><StatCard label="Research requests" value="38" change="24.5%" icon={FlaskConical} color="text-brand-600 bg-brand-100 dark:bg-brand-950/50" /><StatCard label="Meetings summarized" value="26" change="12.8%" icon={FileText} color="text-rose-600 bg-rose-100 dark:bg-rose-950/50" /><StatCard label="Time reclaimed" value="18h 42m" change="31.4%" icon={Clock3} color="text-fuchsia-600 bg-fuchsia-100 dark:bg-fuchsia-950/50" /></div><div className="grid lg:grid-cols-[1.5fr_1fr] gap-6 mb-6"><div className="glass-card p-6"><div className="flex items-center justify-between mb-6"><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Weekly productivity</h3><p className="text-xs text-gray-500 mt-1">AI-assisted activity over the past week</p></div><div className="flex gap-4 text-xs"><span className="flex items-center gap-1.5 text-gray-500"><span className="h-2 w-2 rounded-full bg-brand-500" />Tasks</span><span className="flex items-center gap-1.5 text-gray-500"><span className="h-2 w-2 rounded-full bg-rose-500" />AI sessions</span></div></div><div className="h-64 flex items-end gap-3 border-b border-l border-gray-200 dark:border-gray-700 px-3 pb-0">{[45, 62, 52, 78, 68, 86, 74].map((value, index) => <div key={index} className="flex-1 h-full flex items-end gap-1 justify-center"><div className="w-3/5 max-w-8 bg-brand-500 rounded-t-md" style={{ height: `${value}%` }} /><div className="w-2/5 max-w-5 bg-rose-400 rounded-t-md" style={{ height: `${value * 0.68}%` }} /></div>)}</div><div className="flex justify-between ml-5 pt-3 text-[10px] text-gray-400"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div></div><div className="glass-card p-6"><h3 className="font-display font-bold text-gray-900 dark:text-white">Where time goes</h3><p className="text-xs text-gray-500 mt-1 mb-6">AI usage by workflow</p><div className="relative h-40 w-40 mx-auto mb-5 rounded-full" style={{ background: 'conic-gradient(#ec4899 0 38%, #f43f5e 38% 63%, #d946ef 63% 82%, #f9a8d4 82% 94%, #e5e7eb 94% 100%)' }}><div className="absolute inset-7 rounded-full bg-white dark:bg-gray-900 flex flex-col items-center justify-center"><span className="font-display text-xl font-bold text-gray-900 dark:text-white">18.7h</span><span className="text-[10px] text-gray-400">saved</span></div></div><div className="space-y-2.5"><Legend color="bg-brand-500" label="Writing & communication" value="38%" /><Legend color="bg-rose-500" label="Task planning" value="25%" /><Legend color="bg-fuchsia-500" label="Research" value="19%" /><Legend color="bg-rose-300" label="Meetings" value="12%" /></div></div></div><div className="glass-card p-6"><div className="flex items-center gap-2 mb-5"><div className="h-8 w-8 rounded-lg bg-rose-100 dark:bg-rose-950/50 text-rose-600 flex items-center justify-center"><TrendingUp size={16} /></div><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Your productivity trend</h3><p className="text-xs text-gray-500 mt-1">You are building a sustainable rhythm</p></div></div><div className="grid sm:grid-cols-3 gap-5"><div><p className="text-xs text-gray-500">Daily average</p><p className="font-display text-xl font-bold text-gray-900 dark:text-white mt-1">2h 40m</p><p className="text-xs text-rose-600 mt-1">+22% vs last month</p></div><div><p className="text-xs text-gray-500">Best workflow</p><p className="font-display text-xl font-bold text-gray-900 dark:text-white mt-1">Research</p><p className="text-xs text-gray-500 mt-1">83% time saved</p></div><div><p className="text-xs text-gray-500">Consistency</p><p className="font-display text-xl font-bold text-gray-900 dark:text-white mt-1">92%</p><p className="text-xs text-rose-600 mt-1">+8% this month</p></div></div></div></div>; }
function Legend({ color, label, value }: { color: string; label: string; value: string }) { return <div className="flex items-center gap-2 text-xs"><span className={`h-2.5 w-2.5 rounded-sm ${color}`} /><span className="text-gray-500 flex-1">{label}</span><span className="font-semibold text-gray-700 dark:text-gray-300">{value}</span></div>; }

function SettingsPage({ theme, setTheme }: { theme: Theme; setTheme: (theme: Theme) => void }) { const [saved, setSaved] = useState(false); return <div className="max-w-4xl"><PageHeader eyebrow="Workspace preferences" title="Settings" description="Shape Nexa around the way you work." action={<button onClick={() => { setSaved(true); setTimeout(() => setSaved(false), 2000); }} className="btn-primary">{saved ? <Check size={16} /> : null}{saved ? 'Saved' : 'Save changes'}</button>} /><div className="space-y-5"><SettingsSection title="Profile" description="How you appear across your workspace"><div className="flex items-center gap-4"><div className="h-16 w-16 rounded-2xl bg-gradient-to-br from-brand-400 to-brand-600 flex items-center justify-center text-white text-xl font-bold">OS</div><div><p className="font-semibold text-gray-800 dark:text-gray-200">Oratilwe Seleke</p><p className="text-sm text-gray-500">oratilwe.seleke@company.com</p><button className="text-xs text-brand-600 mt-2 font-medium">Change photo</button></div></div><div className="grid sm:grid-cols-2 gap-4 mt-5"><label><span className="text-xs font-medium text-gray-600 dark:text-gray-400">Full name</span><input value="Oratilwe Seleke" readOnly className="input-field mt-1.5" /></label><label><span className="text-xs font-medium text-gray-600 dark:text-gray-400">Role</span><input value="Administrator" readOnly className="input-field mt-1.5" /></label></div></SettingsSection><SettingsSection title="Appearance" description="Make Nexa feel at home"><div className="flex items-center justify-between py-2"><div><p className="text-sm font-medium text-gray-800 dark:text-gray-200">Color theme</p><p className="text-xs text-gray-500 mt-1">Choose light or dark mode</p></div><div className="flex p-1 rounded-lg bg-gray-100 dark:bg-gray-800"><button onClick={() => setTheme('light')} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium ${theme === 'light' ? 'bg-white dark:bg-gray-700 shadow text-gray-800 dark:text-white' : 'text-gray-500'}`}><Sun size={13} />Light</button><button onClick={() => setTheme('dark')} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium ${theme === 'dark' ? 'bg-white dark:bg-gray-700 shadow text-gray-800 dark:text-white' : 'text-gray-500'}`}><Moon size={13} />Dark</button></div></div></SettingsSection><SettingsSection title="AI preferences" description="Control how Nexa supports your work"><Toggle label="Show AI usage reminders" description="Keep important information reviewable and responsible" enabled /><Toggle label="Include proactive suggestions" description="Surface helpful next steps after each workflow" enabled /><Toggle label="Save conversation history" description="Keep your recent chats available in this session" enabled={false} /></SettingsSection><SettingsSection title="Ethical AI commitment" description="The principles behind a responsible workplace assistant"><div className="grid sm:grid-cols-2 gap-3">{['Review AI-generated content before use', 'Never enter confidential information', 'Respect privacy and data minimization', 'Users remain responsible for decisions', 'Promote fairness and transparency', 'AI outputs are clearly labeled'].map((item) => <div key={item} className="flex gap-2 items-start text-sm text-gray-600 dark:text-gray-400"><CheckCircle2 size={16} className="text-rose-500 shrink-0 mt-0.5" />{item}</div>)}</div></SettingsSection></div></div>; }
function SettingsSection({ title, description, children }: { title: string; description: string; children: React.ReactNode }) { return <section className="glass-card p-6"><h3 className="font-display font-bold text-gray-900 dark:text-white">{title}</h3><p className="text-xs text-gray-500 mt-1 mb-5">{description}</p>{children}</section>; }
function Toggle({ label, description, enabled }: { label: string; description: string; enabled: boolean }) { const [on, setOn] = useState(enabled); return <div className="flex items-center justify-between py-3 border-t border-gray-100 dark:border-gray-800 first:border-0"><div><p className="text-sm font-medium text-gray-800 dark:text-gray-200">{label}</p><p className="text-xs text-gray-500 mt-1">{description}</p></div><button onClick={() => setOn(!on)} className={`w-10 h-6 rounded-full p-1 transition-colors ${on ? 'bg-brand-600' : 'bg-gray-200 dark:bg-gray-700'}`}><span className={`block h-4 w-4 rounded-full bg-white transition-transform ${on ? 'translate-x-4' : ''}`} /></button></div>; }

function About() { return <div className="max-w-5xl mx-auto"><div className="text-center py-10 sm:py-16 animate-fade-in"><div className="h-16 w-16 rounded-2xl bg-gradient-to-br from-brand-400 to-rose-400 flex items-center justify-center text-white shadow-xl shadow-brand-500/20 mx-auto mb-6"><Sparkles size={30} /></div><p className="text-xs font-semibold text-brand-600 dark:text-brand-400 uppercase tracking-widest mb-3">The future of focused work</p><h2 className="font-display text-3xl sm:text-5xl font-extrabold text-gray-900 dark:text-white tracking-tight">Work smarter.<br /><span className="text-gradient">Make room for what matters.</span></h2><p className="text-gray-500 dark:text-gray-400 max-w-xl mx-auto mt-5 leading-relaxed">Nexa is an AI-powered workplace assistant designed to remove repetitive work, amplify good judgment, and give people back their most valuable resource: focused time.</p></div><div className="grid sm:grid-cols-3 gap-4 mb-6"><div className="glass-card p-5 text-center"><p className="font-display text-3xl font-bold text-brand-600">85–90%</p><p className="text-xs text-gray-500 mt-2">average productivity improvement</p></div><div className="glass-card p-5 text-center"><p className="font-display text-3xl font-bold text-rose-600">18.7h</p><p className="text-xs text-gray-500 mt-2">reclaimed by your workspace</p></div><div className="glass-card p-5 text-center"><p className="font-display text-3xl font-bold text-fuchsia-500">100%</p><p className="text-xs text-gray-500 mt-2">human accountability</p></div></div><div className="glass-card p-6 sm:p-8 mb-6"><div className="flex items-center gap-3 mb-5"><div className="h-9 w-9 rounded-xl bg-rose-100 dark:bg-rose-950/50 text-rose-600 flex items-center justify-center"><ShieldIcon /></div><div><h3 className="font-display font-bold text-gray-900 dark:text-white">Our responsible AI promise</h3><p className="text-xs text-gray-500 mt-1">Helpful by design. Thoughtful by default.</p></div></div><div className="grid sm:grid-cols-2 gap-x-8 gap-y-4">{[['Review first', 'AI-generated content should always be reviewed before use.'], ['Protect privacy', 'Do not enter confidential or sensitive company information.'], ['Stay transparent', 'Every AI-generated output is clearly labeled.'], ['Keep humans in charge', 'Users remain responsible for final decisions and outcomes.'], ['Minimize data', 'We do not collect more information than necessary.'], ['Design for fairness', 'We promote accountability, inclusion, and clear explanations.']].map(([title, text]) => <div key={title} className="flex gap-3"><div className="h-6 w-6 rounded-full bg-rose-100 dark:bg-rose-950/50 text-rose-600 flex items-center justify-center shrink-0 mt-0.5"><Check size={13} /></div><div><p className="text-sm font-semibold text-gray-800 dark:text-gray-200">{title}</p><p className="text-xs text-gray-500 mt-1 leading-relaxed">{text}</p></div></div>)}</div></div><p className="text-center text-xs text-gray-400">Nexa Workplace AI · Built for better work, not busier work · v1.0.0</p></div>; }
function ShieldIcon() { return <div className="h-4 w-4 rounded-full border-2 border-current" />; }

export default App;
